-- Alloca Phase 1 baseline schema.
-- Source: docs/database/erd.mmd and the module specifications in docs/specs/.
-- UUIDv7 values are generated by the application, not by PostgreSQL defaults.

create table departments (
    id uuid primary key,
    name varchar(100) not null unique,
    created_at timestamptz not null default current_timestamp
);

create table users (
    id uuid primary key,
    username varchar(100) not null unique,
    email varchar(320) not null unique,
    password_hash varchar(255) not null,
    full_name varchar(150) not null,
    role varchar(20) not null,
    is_active boolean not null default true,
    credentials_version integer not null default 1,
    department_id uuid,
    created_at timestamptz not null default current_timestamp,
    updated_at timestamptz not null default current_timestamp,
    constraint chk_users_role check (role in ('EMPLOYEE', 'MANAGER', 'ADMIN')),
    constraint chk_users_credentials_version check (credentials_version >= 1),
    constraint fk_users_department foreign key (department_id)
        references departments (id) on delete restrict
);

create table zones (
    id uuid primary key,
    name varchar(100) not null,
    floor varchar(50) not null,
    building varchar(100) not null,
    floor_map_url text,
    floor_map_width integer,
    floor_map_height integer,
    constraint chk_zones_floor_map check (
        (floor_map_url is null and floor_map_width is null and floor_map_height is null)
        or (floor_map_url is not null and floor_map_width > 0 and floor_map_height > 0)
    )
);

create table resources (
    id uuid primary key,
    name varchar(100) not null,
    type varchar(20) not null,
    capacity integer not null,
    status varchar(20) not null default 'AVAILABLE',
    description text,
    zone_id uuid not null,
    department_id uuid,
    utilization_threshold numeric(5, 2),
    map_x integer,
    map_y integer,
    map_width integer,
    map_height integer,
    deleted_at timestamptz,
    constraint chk_resources_type check (type in ('ROOM', 'EQUIPMENT', 'DESK')),
    constraint chk_resources_capacity check (capacity >= 1),
    constraint chk_resources_status check (status in ('AVAILABLE', 'SUSPENDED', 'DELETED')),
    constraint chk_resources_threshold check (
        utilization_threshold is null or utilization_threshold between 0 and 100
    ),
    constraint chk_resources_map_position check (
        (map_x is null and map_y is null and map_width is null and map_height is null)
        or (map_x >= 0 and map_y >= 0 and map_width > 0 and map_height > 0)
    ),
    constraint chk_resources_soft_delete check (status <> 'DELETED' or deleted_at is not null),
    constraint fk_resources_zone foreign key (zone_id)
        references zones (id) on delete restrict,
    constraint fk_resources_department foreign key (department_id)
        references departments (id) on delete restrict
);

create table resource_schedules (
    id uuid primary key,
    resource_id uuid not null,
    day_of_week smallint not null,
    start_time time not null,
    end_time time not null,
    constraint chk_resource_schedules_day check (day_of_week between 1 and 7),
    constraint chk_resource_schedules_time_range check (start_time < end_time),
    constraint uq_resource_schedules_window unique (resource_id, day_of_week, start_time, end_time),
    constraint fk_resource_schedules_resource foreign key (resource_id)
        references resources (id) on delete restrict
);

create table bookings (
    id uuid primary key,
    resource_id uuid not null,
    user_id uuid not null,
    created_by uuid not null,
    cancelled_by uuid,
    start_time timestamptz not null,
    end_time timestamptz not null,
    status varchar(20) not null default 'CONFIRMED',
    purpose text,
    cancel_reason text,
    reminder_sent_at timestamptz,
    created_at timestamptz not null default current_timestamp,
    updated_at timestamptz not null default current_timestamp,
    constraint chk_bookings_status check (status in ('CONFIRMED', 'CANCELLED', 'COMPLETED')),
    constraint chk_bookings_time_range check (start_time < end_time),
    constraint fk_bookings_resource foreign key (resource_id)
        references resources (id) on delete restrict,
    constraint fk_bookings_owner foreign key (user_id)
        references users (id) on delete restrict,
    constraint fk_bookings_created_by foreign key (created_by)
        references users (id) on delete restrict,
    constraint fk_bookings_cancelled_by foreign key (cancelled_by)
        references users (id) on delete set null
);

create table booking_status_history (
    id uuid primary key,
    booking_id uuid not null,
    old_status varchar(20),
    new_status varchar(20) not null,
    changed_by uuid,
    reason text,
    changed_at timestamptz not null default current_timestamp,
    constraint chk_booking_history_old_status check (
        old_status is null or old_status in ('CONFIRMED', 'CANCELLED', 'COMPLETED')
    ),
    constraint chk_booking_history_new_status check (
        new_status in ('CONFIRMED', 'CANCELLED', 'COMPLETED')
    ),
    constraint fk_booking_history_booking foreign key (booking_id)
        references bookings (id) on delete restrict,
    constraint fk_booking_history_changed_by foreign key (changed_by)
        references users (id) on delete set null
);

create table alerts (
    id uuid primary key,
    resource_id uuid not null,
    alert_type varchar(50) not null,
    period_start_local date not null,
    period_end_local date not null,
    dedup_key varchar(255) not null unique,
    threshold_percent numeric(5, 2) not null,
    actual_percent numeric(7, 2),
    booked_minutes integer not null,
    available_minutes integer not null,
    status varchar(20) not null default 'OPEN',
    acknowledged_by uuid,
    triggered_at timestamptz not null default current_timestamp,
    resolved_at timestamptz,
    resolution_reason text,
    constraint chk_alerts_type check (alert_type = 'HIGH_UTILIZATION'),
    constraint chk_alerts_period check (period_start_local < period_end_local),
    constraint chk_alerts_threshold check (threshold_percent between 0 and 100),
    constraint chk_alerts_actual_percent check (actual_percent is null or actual_percent >= 0),
    constraint chk_alerts_minutes check (booked_minutes >= 0 and available_minutes >= 0),
    constraint chk_alerts_status check (status in ('OPEN', 'ACKNOWLEDGED', 'RESOLVED')),
    constraint fk_alerts_resource foreign key (resource_id)
        references resources (id) on delete restrict,
    constraint fk_alerts_acknowledged_by foreign key (acknowledged_by)
        references users (id) on delete set null
);

create table notifications (
    id uuid primary key,
    user_id uuid not null,
    booking_id uuid,
    alert_id uuid,
    event_type varchar(30) not null,
    dedup_key varchar(255) not null unique,
    title varchar(200) not null,
    message text not null,
    is_read boolean not null default false,
    created_at timestamptz not null default current_timestamp,
    constraint chk_notifications_event_type check (
        event_type in ('BOOKING_CONFIRMED', 'BOOKING_REMINDER', 'BOOKING_CANCELLED', 'UTILIZATION_ALERT')
    ),
    constraint chk_notifications_reference check (num_nonnulls(booking_id, alert_id) = 1),
    constraint fk_notifications_user foreign key (user_id)
        references users (id) on delete restrict,
    constraint fk_notifications_booking foreign key (booking_id)
        references bookings (id) on delete restrict,
    constraint fk_notifications_alert foreign key (alert_id)
        references alerts (id) on delete restrict
);

create table notification_outbox (
    id uuid primary key,
    booking_id uuid,
    alert_id uuid,
    recipient_id uuid not null,
    event_type varchar(30) not null,
    dedup_key varchar(255) not null unique,
    payload text not null,
    available_at timestamptz not null default current_timestamp,
    processed_at timestamptz,
    attempts integer not null default 0,
    created_at timestamptz not null default current_timestamp,
    constraint chk_notification_outbox_event_type check (
        event_type in ('BOOKING_CONFIRMED', 'BOOKING_REMINDER', 'BOOKING_CANCELLED', 'UTILIZATION_ALERT')
    ),
    constraint chk_notification_outbox_reference check (num_nonnulls(booking_id, alert_id) = 1),
    constraint chk_notification_outbox_attempts check (attempts >= 0),
    constraint fk_notification_outbox_booking foreign key (booking_id)
        references bookings (id) on delete restrict,
    constraint fk_notification_outbox_alert foreign key (alert_id)
        references alerts (id) on delete restrict,
    constraint fk_notification_outbox_recipient foreign key (recipient_id)
        references users (id) on delete restrict
);

create table app_settings (
    singleton_id smallint primary key,
    reminder_lead_minutes integer not null default 15,
    updated_at timestamptz not null default current_timestamp,
    updated_by uuid,
    constraint chk_app_settings_singleton check (singleton_id = 1),
    constraint chk_app_settings_reminder_lead check (reminder_lead_minutes between 1 and 1440),
    constraint fk_app_settings_updated_by foreign key (updated_by)
        references users (id) on delete set null
);

create table activity_logs (
    id uuid primary key,
    user_id uuid,
    action varchar(100) not null,
    entity_type varchar(100) not null,
    entity_id uuid not null,
    metadata text,
    ip_address varchar(45),
    created_at timestamptz not null default current_timestamp,
    constraint fk_activity_logs_user foreign key (user_id)
        references users (id) on delete set null
);

create index idx_users_auth_state on users (id, is_active, credentials_version);
create index idx_users_department on users (department_id);
create index idx_resources_zone on resources (zone_id);
create index idx_resources_department_status on resources (department_id, status);
create index idx_resource_schedules_resource_day on resource_schedules (resource_id, day_of_week);
create index idx_bookings_resource_status_start_end on bookings (resource_id, status, start_time, end_time);
create index idx_bookings_owner_start on bookings (user_id, start_time desc);
create index idx_booking_status_history_booking_changed_at on booking_status_history (booking_id, changed_at desc);
create index idx_alerts_resource_status on alerts (resource_id, status);
create index idx_notifications_user_read_created_at on notifications (user_id, is_read, created_at desc);
create index idx_notification_outbox_pending on notification_outbox (available_at) where processed_at is null;
create index idx_activity_logs_user_created_at on activity_logs (user_id, created_at desc);

insert into app_settings (singleton_id, reminder_lead_minutes)
values (1, 15);
